SELECT p.gender, CASE WHEN p.age >= 86 AND p.age <= 96 THEN '86-96' ELSE 'Other' END AS age_group, d.name AS diagnosis, ph.classification AS drug_class, COUNT(*)::FLOAT / (SELECT COUNT(*) FROM admissions a JOIN patients pt ON a.subject_id = pt.subject_id JOIN diagnoses_icd dc ON a.subject_id = dc.subject_id JOIN prescriptions pr ON a.subject_id = pr.subject_id AND a.hadm_id = pr.hadm_id JOIN pharmacy ph ON pr.pharmacy_id = ph.pharmacy_id AND pr.poe_id = ph.poe_id WHERE pt.gender = p.gender AND age_group = CASE WHEN pt.age >= 86 AND pt.age <= 96 THEN '86-96' ELSE 'Other' END AND dc.name = d.name AND ph.classification IN ('Insulin', 'Oral Agents') AND a.admittime BETWEEN 0 AND 12 AND a.dischtime BETWEEN 72 AND 96) * 100 AS proportion FROM admissions a JOIN patients pt ON a.subject_id = pt.subject_id JOIN diagnoses_icd dc ON a.subject_id = dc.subject_id JOIN prescriptions pr ON a.subject_id = pr.subject_id AND a.hadm_id = pr.hadm_id JOIN pharmacy ph ON pr.pharmacy_id = ph.pharmacy_id AND pr.poe_id = ph.poe_id WHERE pt.gender = p.gender AND age_group = CASE WHEN pt.age >= 86 AND pt.age <= 96 THEN '86-96' ELSE 'Other' END AND dc.name = d.name AND ph.classification IN ('Insulin', 'Oral Agents') AND a.admittime BETWEEN 0 AND 12 AND a.dischtime BETWEEN 72 AND 96 GROUP BY p.gender, age_group, d.name, drug_class;